        if (mask & (1 << j)) and (mask & (1 << (j + 1))):
            return False
    return True

def is_valid_transition(prev_mask, curr_mask, m):
    for j in range(m):
        if (prev_mask & (1 << j)) and (curr_mask & (1 << j)):
            if j > 0 and (prev_mask & (1 << (j - 1))):
                return False
            if j < m - 1 and (prev_mask & (1 << (j + 1))):
                return False
        elif (prev_mask & (1 << j)) and (curr_mask & (1 << j)):
            if j > 0 and (curr_mask & (1 << (j - 1))):
                return False
            if j < m - 1 and (curr_mask & (1 << (j + 1))):
                return False
    return True

